import{_ as a,b as e,c as o,I as i}from"./chunks/framework.C6cPs9Ia.js";const d=JSON.parse('{"title":"我喜欢的画师和角色：猫羽雫","description":"记录我喜欢的一位画师甘城なつき，和她笔下的角色猫羽雫","frontmatter":{"title":"我喜欢的画师和角色：猫羽雫","date":"2026-09-16T00:00:00.000Z","tags":["画画","猫羽雫","日常"],"pinned":true,"cover":"/LQY/images/cover-a.jpg","head":[["meta",{"name":"description","content":"记录我喜欢的一位画师甘城なつき，和她笔下的角色猫羽雫"}],["meta",{"name":"keywords","content":"猫羽雫, Nekoha Shizuku, 甘城なつき, Nachoneko, 画师"}]]},"headers":[],"relativePath":"posts/neko-shizuku.md","filePath":"posts/neko-shizuku.md"}'),r={name:"posts/neko-shizuku.md"};function n(s,t,l,u,h,p){return e(),o("div",null,[...t[0]||(t[0]=[i('<p>想认真写一篇介绍自己喜欢的画师的文章。她叫<strong>甘城なつき</strong>（Nachoneko），是 Pixiv 上的一位日本插画师，我用了很久的手机壁纸、表情包，基本都是她的作品。</p><hr><h2 id="从一张壁纸开始" tabindex="-1">从一张壁纸开始 <a class="header-anchor" href="#从一张壁纸开始" aria-label="Permalink to &quot;从一张壁纸开始&quot;">​</a></h2><p>记得是初二还是初三的时候，我在找新壁纸，刷到一张图：蓝发蓝瞳的猫耳少女，半马尾别着发珠，露出一颗小虎牙，怀里抱着一只猫玩偶。当时只觉得配色舒服，画风干净，顺手存了下来。</p><p>后来又一次刷到同风格的图，才顺着画师名找了过去——原来那个角色叫<strong>猫羽雫</strong>（ねこはしずく / Nekoha Shizuku），是甘城なつき的原创角色，也是她自己的&quot;看板娘&quot;，很多自我介绍图、表情包都由她出镜。</p><h2 id="角色档案" tabindex="-1">角色档案 <a class="header-anchor" href="#角色档案" aria-label="Permalink to &quot;角色档案&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">猫羽雫小档案</p><ul><li><strong>生日</strong>：6 月 24 日</li><li><strong>身高</strong>：149cm</li><li><strong>形象</strong>：蓝发蓝瞳、猫耳、虎牙、半马尾</li><li><strong>性格</strong>：爱吃、爱睡、爱玩，偶尔傲娇</li><li><strong>标配</strong>：一只叫&quot;猫酱&quot;的玩偶</li></ul></div><p>这个角色没有什么宏大的故事背景，她大多出现在画师的日常涂鸦里：赖床、吃零食、打游戏、和玩偶说话。可能正因为这样，反而显得真实——她过的是一种很轻松的生活。</p><h2 id="为什么喜欢" tabindex="-1">为什么喜欢 <a class="header-anchor" href="#为什么喜欢" aria-label="Permalink to &quot;为什么喜欢&quot;">​</a></h2><p>一方面是画本身好看。甘城なつき的用色以蓝色和白色为主，线条简单但细节到位，尤其是眼神和嘴角的处理，很传神。</p><p>另一方面是气质。她笔下这个角色不太吵，安安静静的，带一点点小情绪，但整体是治愈的。写作业写累了抬头看到桌上的立牌，心情会好一点，就这么简单。</p><h2 id="收集情况" tabindex="-1">收集情况 <a class="header-anchor" href="#收集情况" aria-label="Permalink to &quot;收集情况&quot;">​</a></h2><p>这几年陆陆续续攒了一些：</p><ul><li>立牌两个，一个在书桌，一个在床头</li><li>LINE 表情包（聊天时偶尔用，朋友们已经认识她了）</li><li>手机、电脑壁纸三端统一</li><li>猫酱玩偶的同款大号还在购物车里，等零花钱到位</li></ul><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>如果你也喜欢这种风格的插画，推荐去 Pixiv 搜&quot;甘城なつき&quot;，她的作品更新很稳定。6 月 24 日是这个角色的生日，每年那天我都会换个新壁纸，算是小小的仪式。</p><p>当然，萝卜青菜各有所爱，欢迎在评论区聊聊你喜欢的画师和角色。</p>',17)])])}const k=a(r,[["render",n]]);export{d as __pageData,k as default};
